import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 30 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"30","title":"Page 30 | Home","prev":"/page/29/","next":"/page/31/","posts":[{"title":"解压和打包安卓DAT文件","url":"/posts/2015-07-28-compression-and-decompression-dat-files/","date":"2015-7-28 19:54","tags":["notes"],"html":"<p>安卓 5.0 的卡刷包系统基本上都是在一个 dat 文件里面的。但是对于很多国内 ROM，要不就是植入了很多流氓软件，\\n要不就是有很多无用软件。我们可以通过解压 DAT 文件并进行修改然后再封装回去就完美啦～</p>\\n<h2 id=\\"首先把-dat-解压成-img-镜像\\" tabindex=\\"-1\\">首先把 DAT 解压成 IMG 镜像 <a class=\\"header-anchor\\" href=\\"#首先把-dat-解压成-img-镜像\\" aria-label=\\"Permalink to &quot;首先把 DAT 解压成 IMG 镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们要使用<a href=\\"https://github.com/xpirt/sdat2img\\" target=\\"_blank\\" rel=\\"noreferrer\\">sdat2img</a>工具把 DAT 文件转换成 IMG 镜像</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./sdat2img</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">transfer_lis</span><span style=\\"color:#24292E\\">t</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_new_fil</span><span style=\\"color:#24292E\\">e</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_ext</span><span style=\\"color:#D73A49\\">4></span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">-</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">transfer_lis</span><span style=\\"color:#24292E\\">t</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> input,</span><span style=\\"color:#032F62\\"> system.transfer.list</span><span style=\\"color:#032F62\\"> from</span><span style=\\"color:#032F62\\"> rom</span><span style=\\"color:#032F62\\"> zip</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">-</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_new_fil</span><span style=\\"color:#24292E\\">e</span><span style=\\"color:#D73A49\\">></span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> input,</span><span style=\\"color:#032F62\\"> system.new.dat</span><span style=\\"color:#032F62\\"> from</span><span style=\\"color:#032F62\\"> rom</span><span style=\\"color:#032F62\\"> zip</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">-</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_ext</span><span style=\\"color:#D73A49\\">4></span><span style=\\"color:#032F62\\"> =</span><span style=\\"color:#032F62\\"> output</span><span style=\\"color:#032F62\\"> ext4</span><span style=\\"color:#032F62\\"> raw</span><span style=\\"color:#032F62\\"> image</span><span style=\\"color:#032F62\\"> file</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>一个很简单的例子:</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./sdat2img</span><span style=\\"color:#032F62\\"> system.transfer.list</span><span style=\\"color:#032F62\\"> system.new.dat</span><span style=\\"color:#032F62\\"> system.img</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>新生成的 IMG 镜像便是我们下一步需要的.</p>\\n<h2 id=\\"挂载-img-镜像\\" tabindex=\\"-1\\">挂载 IMG 镜像 <a class=\\"header-anchor\\" href=\\"#挂载-img-镜像\\" aria-label=\\"Permalink to &quot;挂载 IMG 镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">sudo</span><span style=\\"color:#032F62\\"> mount</span><span style=\\"color:#005CC5\\"> -t</span><span style=\\"color:#032F62\\"> ext4</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> loop</span><span style=\\"color:#032F62\\"> system.img</span><span style=\\"color:#032F62\\"> /mnt/android</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这时候你可以在系统的 /mnt/android 目录下看到文件的具体内容然后进行修改了.</p>\\n<h2 id=\\"打包回-img-镜像\\" tabindex=\\"-1\\">打包回 IMG 镜像 <a class=\\"header-anchor\\" href=\\"#打包回-img-镜像\\" aria-label=\\"Permalink to &quot;打包回 IMG 镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>把修改好的内容打包回去需要使用<a href=\\"https://github.com/EpicAOSP/make_ext4\\" target=\\"_blank\\" rel=\\"noreferrer\\">make_ext4</a>工具</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./make_ext4fs</span><span style=\\"color:#005CC5\\"> -T</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#005CC5\\"> -S</span><span style=\\"color:#032F62\\"> file_contexts</span><span style=\\"color:#005CC5\\"> -l</span><span style=\\"color:#005CC5\\"> 1073741824</span><span style=\\"color:#005CC5\\"> -a</span><span style=\\"color:#032F62\\"> system</span><span style=\\"color:#032F62\\"> system_new.img</span><span style=\\"color:#032F62\\"> /mnt/android</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>file_contexts 文件是 ROM 本身提供的.后面的一串数字指的是打包的 IMG 文件的大小 1G</p>\\n<h2 id=\\"封装成-dat-文件\\" tabindex=\\"-1\\">封装成 DAT 文件 <a class=\\"header-anchor\\" href=\\"#封装成-dat-文件\\" aria-label=\\"Permalink to &quot;封装成 DAT 文件&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>封装仍需要使用工具 使用 <a href=\\"https://mega.co.nz/#!IRAi0SKL!nof6p9JmFhGQNgnNmdEKWiEwZ9NOFUVv4q9BQZfM95w\\" target=\\"_blank\\" rel=\\"noreferrer\\">rimg2sdat</a></p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">./rimg2sdat</span><span style=\\"color:#D73A49\\"> &#x3C;</span><span style=\\"color:#032F62\\">system_im</span><span style=\\"color:#24292E\\">g</span><span style=\\"color:#D73A49\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样就打包好了新的 DAT 文件,放入刷机 ROM.刷机即可~ 以上操作最好在 Linux 环境下,Win 下不保证成功.</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"http://forum.xda-developers.com/android/software-hacking/how-to-conver-lollipop-dat-files-to-t2978952\\" target=\\"_blank\\" rel=\\"noreferrer\\">XDA</a></p>\\n"},{"title":"突破同源策略限制的方法","url":"/posts/2015-04-20-breaking-the-same-origin-policy/","date":"2015-4-20 19:54","tags":["js"],"html":"<h2 id=\\"同源策略基本介绍\\" tabindex=\\"-1\\">同源策略基本介绍 <a class=\\"header-anchor\\" href=\\"#同源策略基本介绍\\" aria-label=\\"Permalink to &quot;同源策略基本介绍&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>同源策略（Same Origin Policy）是一种约定，它是浏览器最核心也是最基本的安全功能，如果缺少了同源策略，则浏览器的正常功能可能会受到影响。可以说 Web 是构建在同源策略的基础之上的，浏览器只是针对同源策略的一种实现。</p>\\n<p><strong>浏览器的同源策略，限制了来自不同源的“document”或脚本，对当前“document”读取或设置某些属性。</strong></p>\\n<p>但是随着互联网的发展跨域的需求也越来越迫切，有些时候我们需要突破同源策略。下面开始介绍突破同源策略的几种方法：</p>\\n<h2 id=\\"使用-http-头\\" tabindex=\\"-1\\">使用 HTTP 头 <a class=\\"header-anchor\\" href=\\"#使用-http-头\\" aria-label=\\"Permalink to &quot;使用 HTTP 头&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>因为 JavaScript 无法控制返回的 HTTP 头，所以可以在服务器端这个 HTTP Header 即可：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>self.set_header(\\"Access-Control-Allow-Origin\\", \\"*\\")</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"使用-jsonp\\" tabindex=\\"-1\\">使用 JSONP <a class=\\"header-anchor\\" href=\\"#使用-jsonp\\" aria-label=\\"Permalink to &quot;使用 JSONP&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Jsonp(JSON with Padding)是 json 的一种“使用模式”，可以让网页从别的网域获取资料。jsonp 是采用的 js 的回调机制来实现的。\\n本质上是因为 GET 方法不受同源策略限制，然后获取到的数据不是 json，而是一段 JavaScript 并解释执行。</p>\\n<h2 id=\\"使用-iframe\\" tabindex=\\"-1\\">使用 iframe <a class=\\"header-anchor\\" href=\\"#使用-iframe\\" aria-label=\\"Permalink to &quot;使用 iframe&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>上面两种都是比较常见和常用的突破浏览器的方法，这种不常见的才是重点。虽然使用 iframe 算不上优雅，但也算开了眼界。在开发 115 网盘的时候，发现 115\\n的主站网页和获取数据的网址是不同源的，也顺便研究了一下工作原理。<br>\\n主站是：<a href=\\"http://115.com/?mode=wangpan%EF%BC%8C\\" target=\\"_blank\\" rel=\\"noreferrer\\">http://115.com/?mode=wangpan，</a><br>\\n但是获取数据的 API 是：<a href=\\"http://web.api.115.com/files/download?pickcode=%EF%BC%9F\\" target=\\"_blank\\" rel=\\"noreferrer\\">http://web.api.115.com/files/download?pickcode=？</a><br>\\n这就造成了非同源，但是 115 巧妙的使用了一个桥接网页完成了跨域操作！<br>\\n桥接网址：<a href=\\"http://web.api.115.com/bridge_2.0.html?namespace=DownBridge&amp;api=jQuery\\" target=\\"_blank\\" rel=\\"noreferrer\\">http://web.api.115.com/bridge_2.0.html?namespace=DownBridge&amp;api=jQuery</a><br>\\n关键代码：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">if</span><span style=\\"color:#24292E\\"> (parent) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> execObj </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> parent.window;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (params[</span><span style=\\"color:#032F62\\">'namespace'</span><span style=\\"color:#24292E\\">]) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> tmp </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> params[</span><span style=\\"color:#032F62\\">'namespace'</span><span style=\\"color:#24292E\\">].</span><span style=\\"color:#6F42C1\\">split</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'.'</span><span style=\\"color:#24292E\\">),</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      f;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    while</span><span style=\\"color:#24292E\\"> ((f </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> tmp.</span><span style=\\"color:#6F42C1\\">shift</span><span style=\\"color:#24292E\\">())) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      execObj </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> execObj[f];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  var</span><span style=\\"color:#24292E\\"> method </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> params[</span><span style=\\"color:#032F62\\">'api'</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">?</span><span style=\\"color:#24292E\\"> params[</span><span style=\\"color:#032F62\\">'api'</span><span style=\\"color:#24292E\\">] </span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#032F62\\"> 'DataAPI'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  execObj[method] </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> $;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><p>可以看到，桥接是首先判断父 Window 是否存在，获取 namespace 的值设置为 execObj 最后再获取 api 的值然后设置为 execObj 的一个方法，不过这个方法对应的值肯定是 $,也就是整个 JQuery，这样我们就可以使用页面 web.api.115.com 的 JQuery 发起数据请求从而绕过跨越的限制。</p>\\n<p>下面是 115.com 上面注入的 JS 实现方法：</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">set_down_url</span><span style=\\"color:#24292E\\">:</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\">(){</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    var</span><span style=\\"color:#24292E\\"> self</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\">this</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    DownBridge</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">      $</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'&#x3C;iframe>'</span><span style=\\"color:#24292E\\">).</span><span style=\\"color:#6F42C1\\">attr</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'src'</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#032F62\\">'http://web.api.115.com/bridge_2.0.html?namespace=DownBridge&#x26;api=jQuery'</span><span style=\\"color:#24292E\\">).</span><span style=\\"color:#6F42C1\\">css</span><span style=\\"color:#24292E\\">({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        width: </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        height: </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        border: </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        padding: </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        margin: </span><span style=\\"color:#005CC5\\">0</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        position: </span><span style=\\"color:#032F62\\">'absolute'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        top: </span><span style=\\"color:#032F62\\">'-99999px'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }).</span><span style=\\"color:#6F42C1\\">one</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'load'</span><span style=\\"color:#24292E\\">,</span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\">(){</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        window.DownBridge.</span><span style=\\"color:#6F42C1\\">getFileUrl</span><span style=\\"color:#D73A49\\">=function</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">pickcode</span><span style=\\"color:#24292E\\">,</span><span style=\\"color:#E36209\\">callback</span><span style=\\"color:#24292E\\">){</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">        this</span><span style=\\"color:#24292E\\">.jQuery.</span><span style=\\"color:#6F42C1\\">get</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'http://web.api.115.com/files/download?pickcode='</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> pickcode, </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">data</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">                  callback</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                }, </span><span style=\\"color:#032F62\\">'json'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        window.DownBridge.</span><span style=\\"color:#6F42C1\\">getFileList</span><span style=\\"color:#D73A49\\">=function</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">cate_id</span><span style=\\"color:#24292E\\">,</span><span style=\\"color:#E36209\\">callback</span><span style=\\"color:#24292E\\">){</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">        this</span><span style=\\"color:#24292E\\">.jQuery.</span><span style=\\"color:#6F42C1\\">get</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'http://web.api.115.com/files?aid=1&#x26;limit=1000&#x26;show_dir=1&#x26;cid='</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> cate_id, </span><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#E36209\\">data</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">                  callback</span><span style=\\"color:#24292E\\">(data);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">                }, </span><span style=\\"color:#032F62\\">'json'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      }).</span><span style=\\"color:#6F42C1\\">appendTo</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'html'</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br></div></div><p>115 网站的这种实现方法很另类，不知道是否是有什么特殊需求导致的，但是很有意思～\\n不过我还是不建议在网页里嵌入这么多的 iframe，严重影响用户体验，非常不推荐！</p>\\n"},{"title":"Chromebook Pixel (2013) 安装Linux的方法","url":"/posts/2015-04-20-chromebook-pixel-install-linux/","date":"2015-4-20 19:54","tags":["chrome"],"html":"<p>同学最近淘了一台二手 Chromebook Pixel (2013)，这款笔记本最大的诱惑就是 12.85 寸但是配备了一块 2560 x 1700 分辨率的触摸屏。上网的体验不要太爽啊，在体验了一小时的 Chrome OS 之后，便感叹就只有一个浏览器而已啊！于是开始折腾如何安装 Linux，毕竟这款笔记本本来就对 Linux 支持很好。下面开始介绍安装过程。</p>\\n<p>由于这款笔记本是 x86 架构还自带 SeaBIOS，所以在安装 Linux 上省了不少功夫，很多非 SeaBIOS 的 Chromebook 都是需要刷固件才能引导 Linux 的。</p>\\n<h2 id=\\"启用开发者模式\\" tabindex=\\"-1\\">启用开发者模式 <a class=\\"header-anchor\\" href=\\"#启用开发者模式\\" aria-label=\\"Permalink to &quot;启用开发者模式&quot;\\">&ZeroWidthSpace;</a></h2>\\n<ul>\\n<li>启动电脑</li>\\n<li>按住 Esc 和 F3（刷新）按钮，这时候按电源键，即可进入 Recovery 模式</li>\\n<li>按 Ctrl+ D，会提示你是否要进入开发者模式，确认之后等一会系统就会转变成启用开发者模式</li>\\n</ul>\\n<p>这时候每次开机屏幕都有警告提示，要么按 Ctrl + D，或者等待 30s 系统响一声便进入系统。</p>\\n<h2 id=\\"进入超级用户-shell\\" tabindex=\\"-1\\">进入超级用户 shell <a class=\\"header-anchor\\" href=\\"#进入超级用户-shell\\" aria-label=\\"Permalink to &quot;进入超级用户 shell&quot;\\">&ZeroWidthSpace;</a></h2>\\n<ul>\\n<li>按 Ctrl+Alt+F2（→），之后你会看到一个登录提示</li>\\n<li>输入 <code>chronos</code> 作为用户名，没有密码</li>\\n<li>然后输入 <code>sudo bash</code>,以超级用户使用 shell</li>\\n</ul>\\n<h2 id=\\"启用-seabios\\" tabindex=\\"-1\\">启用 SeaBIOS <a class=\\"header-anchor\\" href=\\"#启用-seabios\\" aria-label=\\"Permalink to &quot;启用 SeaBIOS&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在终端里面输入下面的指令：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># crossystem dev_boot_usb=1 dev_boot_legacy=1</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>之后重启电脑即可。之后每次进入 SeaBIOS 都要在开机的时候按 Ctrl + L</p>\\n<h2 id=\\"将-seabios-设置成默认启动\\" tabindex=\\"-1\\">将 SeaBIOS 设置成默认启动 <a class=\\"header-anchor\\" href=\\"#将-seabios-设置成默认启动\\" aria-label=\\"Permalink to &quot;将 SeaBIOS 设置成默认启动&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先你需要破解硬件写保护，按照 wiki 上的说法需要拆机和跳线，具体的操作可以查看这个<a href=\\"https://www.chromium.org/chromium-os/developer-information-for-chrome-os-devices/chromebook-pixel\\" target=\\"_blank\\" rel=\\"noreferrer\\">wiki</a>,拆机操作非常危险，请自己慎重考虑。</p>\\n<p>如果你已经成功破解硬件写保护，接下来就是解除软件写保护。同样是进入超级用户 shell 然后输入指令禁用软件写保护：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># flashrom --wp-disable</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>检查软件写保护：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># flashrom --wp-status</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>运行 set_gbb_flags.sh ：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># set_gbb_flags.sh</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>注意：新版本的 Chrome OS 已经把这个脚本移动到 <code>/usr/share/vboot/bin/set_gbb_flags.sh</code>位置了，然而并不在$PATH 环境变量中。</p>\\n<p>确认有下面的输出：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>GBB_FLAG_DEV_SCREEN_SHORT_DELAY 0x00000001</span></span>\\n<span class=\\"line\\"><span>GBB_FLAG_FORCE_DEV_SWITCH_ON 0x00000008</span></span>\\n<span class=\\"line\\"><span>GBB_FLAG_FORCE_DEV_BOOT_LEGACY 0x00000080</span></span>\\n<span class=\\"line\\"><span>GBB_FLAG_DEFAULT_DEV_BOOT_LEGACY 0x00000400</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><p>现在可以设置 SeaBIOS 为默认了：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># set_gbb_flags.sh 0x489</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>最后再重新启用写保护：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6A737D\\"># flashrom --wp-enable</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>现在可以使用 Linux 安装 U 盘进行安装了。</p>\\n<h2 id=\\"写在最后\\" tabindex=\\"-1\\">写在最后 <a class=\\"header-anchor\\" href=\\"#写在最后\\" aria-label=\\"Permalink to &quot;写在最后&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>插上 U 盘，开机然后按 Ctrl+ L 发现启动光盘正常启动，然后选择安装之后突然提示。。。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>not enough memory to load specified image</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这时候不要慌张，在安装选择菜单点击 Tab 键，可以编辑启动命令，在双横线前面输入 <code>mem=4G</code> 注意是双横线前面！</p>\\n<p>恢复 Chrome OS，请参阅<a href=\\"https://support.google.com/chromebook/answer/1080595?hl=en\\" target=\\"_blank\\" rel=\\"noreferrer\\">Recover your Chromebook</a></p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://wiki.archlinux.org/index.php/Chrome_OS_devices\\" target=\\"_blank\\" rel=\\"noreferrer\\">Chrome OS devices</a></p>\\n<p><a href=\\"https://wiki.archlinux.org/index.php/Chrome_OS_devices/Chromebook\\" target=\\"_blank\\" rel=\\"noreferrer\\">Chromebook</a></p>\\n<p><a href=\\"http://vger.kernel.org/~davem/chromebook_pixel_linux.txt\\" target=\\"_blank\\" rel=\\"noreferrer\\">Installing Linux on the Chromebook Pixel</a></p>\\n"}]},"relativePath":"page/30/index.md","filePath":"page/[page].md"}`),e={name:"page/30/index.md"};function l(p,o,r,t,c,i){return a(),n("div")}const y=s(e,[["render",l]]);export{b as __pageData,y as default};
